customCSS:
@font-face {
    font-family: 'LeeSunSinDotum';
    src: url('https://cdn.jsdelivr.net/gh/projectnoonnu/noonfonts_two@1.0/YiSunShinDotumM.woff') format('woff');
    font-weight: normal;
    font-display: swap;
}
@font-face {
    font-family: 'Orbit';
    src: url('https://cdn.jsdelivr.net/gh/projectnoonnu/noonfonts_2310@1.0/Orbit-Regular.woff2') format('woff2');
    font-weight: normal;
    font-display: swap;
}
:root {
  --hz-yellow: #f5c400;
  --hz-black: #111;
  --hz-paper: #eeeade;
}

/* 기본 경고 박스 */
.hz-box {
  overflow: hidden;
  color: var(--hz-black);
  background: var(--hz-yellow);
  border: 3px solid var(--hz-black);
  box-shadow: 6px 6px 0 var(--hz-black);
  font-family: "Courier New", monospace;
}

/* 상단 경고띠 */
.hz-tape {
  overflow: hidden;
  padding: 7px 0;
  color: var(--hz-yellow);
  background: var(--hz-black);
  white-space: nowrap;
}

.hz-tape__track {
  display: inline-block;
  min-width: 200%;
  font-weight: 700;
  animation: hz-scroll 18s linear infinite;
}

.hz-tape:hover .hz-tape__track {
  animation-play-state: paused;
}

/* 본문 */
.hz-content {
  padding: clamp(20px, 4vw, 38px);
}

.hz-label {
  display: inline-block;
  margin-bottom: 14px;
  padding: 4px 7px;
  color: var(--hz-yellow);
  background: var(--hz-black);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.hz-title {
  margin: 0 0 12px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(2.5rem, 8vw, 6rem);
  line-height: 0.9;
  text-transform: uppercase;
}

.hz-text {
  max-width: 55ch;
  margin: 0 0 22px;
  line-height: 1.55;
}

/* 가벼운 호버 */
.hz-hover {
  transition:
    transform 150ms ease,
    box-shadow 150ms ease;
}

.hz-hover:hover {
  transform: translate(-3px, -3px);
  box-shadow: 9px 9px 0 var(--hz-black);
}

/* 버튼 */
.hz-button {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  padding: 10px 15px;

  color: var(--hz-yellow);
  background: var(--hz-black);
  border: 2px solid var(--hz-black);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--hz-paper);

  font: 700 0.9rem/1 "Courier New", monospace;
  text-decoration: none;
  cursor: pointer;

  transition:
    transform 100ms ease,
    box-shadow 100ms ease;
}

.hz-button:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--hz-paper);
}

.hz-button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.hz-button:focus-visible {
  outline: 3px solid var(--hz-black);
  outline-offset: 4px;
}

@keyframes hz-scroll {
  to {
    transform: translateX(-50%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hz-tape__track {
    animation: none;
  }

  .hz-hover,
  .hz-button {
    transition: none;
  }
}

/* ICCPLUS_CONDITION_DRAW_START */
/* Internal condition flags are never shown to the reader. */
.row-row-hlpr-bg,
.row-bg-row-hlpr {
  display: none !important;
}

/* Unopened, RANDOM-opened, and debug-opened abilities retain the authored NaN label. */
.row-row-pvvq-bg {
  counter-reset: drawn-ability;
}

/* Only the nine conditions created by the draw receive I-IX and move first. */
.ab-0:has(.choice-choice-dh01.choice-selected) .choice-choice-tmgw {
  counter-increment: drawn-ability;
}
.ab-0:has(.choice-choice-dh01.choice-selected) .choice-choice-tmgw .ability-number-nan {
  -webkit-text-fill-color: transparent !important;
}
.ab-0:has(.choice-choice-dh01.choice-selected) .choice-choice-tmgw .ability-number-nan::before {
  content: counter(drawn-ability, upper-roman);
  display: inline-block;
  width: 3ch;
  margin-right: -3ch;
  text-align: center;
  vertical-align: baseline;
  -webkit-text-fill-color: currentColor;
}
.ab-0:has(.choice-choice-dh01.choice-selected) .row-row-pvvq-bg > .row.gx-0.m-0.p-0 > div:has(.choice-choice-tmgw) {
